import { z } from "zod";
import { SHAPE_FILLS, SHAPE_KINDS } from "./shape";
import { MAX_STICKY_BYTES, MAX_WRAP_WIDTH } from "./sticky";
import { DEFAULT_STROKE_STYLE, STROKE_STYLES } from "./style";
import {
  DEFAULT_TEXT_FIT,
  DEFAULT_TEXT_FONT,
  HREF_PATTERN,
  MAX_HREF_BYTES,
  TEXT_FITS,
  TEXT_FONTS,
} from "./text-style";
import { MAX_WIDTH, MIN_WIDTH } from "./width";

export const objectId = z.string().regex(/^[0-9A-Za-z_-]{1,64}$/);

export const nativeZoom = z.int().min(-40).max(40);

export const bbox = z.strictObject({
  minX: z.number(),
  minY: z.number(),
  maxX: z.number(),
  maxY: z.number(),
});

export const colour = z.int().min(0).max(5);

export const rgb = z.int().min(0).max(0xffffff);

export const width = z.number().min(MIN_WIDTH).max(MAX_WIDTH);

export const strokeStyle = z.enum(STROKE_STYLES).default(DEFAULT_STROKE_STYLE);

export const pencilSize = z.enum(["Small", "Medium", "Large"]);

export const point = z.tuple([z.number(), z.number(), z.number().min(0).max(1)]);

export const shapePoint = z.tuple([z.number(), z.number()]);

export const textFont = z.enum(TEXT_FONTS).default(DEFAULT_TEXT_FONT);

export const textFit = z.enum(TEXT_FITS).default(DEFAULT_TEXT_FIT);

export const href = z.string().max(MAX_HREF_BYTES).regex(new RegExp(HREF_PATTERN));

const textStyle = {
  font: textFont,
  bold: z.boolean().default(false),
  italic: z.boolean().default(false),
  href: href.optional(),
  fit: textFit,
};

export const stroke = z.strictObject({
  type: z.literal("Stroke"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  rgb: rgb.optional(),
  size: pencilSize,
  width: width.optional(),
  style: strokeStyle,
  points: z.array(point).min(1).max(4096),
});

export const shape = z.strictObject({
  type: z.literal("Shape"),
  objectId,
  nativeZoom,
  bbox,
  colour,
  rgb: rgb.optional(),
  size: pencilSize,
  width: width.optional(),
  style: strokeStyle,
  kind: z.enum(SHAPE_KINDS),
  start: shapePoint,
  end: shapePoint,
  fill: z.enum(SHAPE_FILLS),
});

export const text = z.strictObject({
  type: z.literal("Text"),
  objectId,
  nativeZoom,
  bbox,
  rgb,
  width,
  wrapWidth: z.number().gt(0).max(MAX_WRAP_WIDTH),
  text: z.string().min(1).max(MAX_STICKY_BYTES),
  ...textStyle,
});

export const sticky = z.strictObject({
  type: z.literal("Sticky"),
  objectId,
  nativeZoom,
  bbox,
  rgb,
  background: rgb,
  width,
  text: z.string().max(MAX_STICKY_BYTES),
  ...textStyle,
});

export const stallionObject = z.discriminatedUnion("type", [stroke, shape, text, sticky]);

export type Bbox = z.infer<typeof bbox>;
export type Point = z.infer<typeof point>;
export type ShapePoint = z.infer<typeof shapePoint>;
export type PencilSize = z.infer<typeof pencilSize>;
export type Stroke = z.infer<typeof stroke>;
export type Shape = z.infer<typeof shape>;
export type Text = z.infer<typeof text>;
export type Sticky = z.infer<typeof sticky>;
export type StallionObject = z.infer<typeof stallionObject>;
export const SHAPE_KINDS = ["Rectangle", "Ellipse", "Line", "Arrow"] as const;

export type ShapeKind = (typeof SHAPE_KINDS)[number];

export const SHAPE_FILLS = ["None", "Tint"] as const;

export type ShapeFill = (typeof SHAPE_FILLS)[number];

export const FILLABLE: Readonly<Record<ShapeKind, boolean>> = {
  Rectangle: true,
  Ellipse: true,
  Line: false,
  Arrow: false,
};
export const TEXT_FONTS = ["Sans", "Serif", "Mono", "Hand"] as const;

export type TextFont = (typeof TEXT_FONTS)[number];

export const DEFAULT_TEXT_FONT: TextFont = "Sans";

export const TEXT_FITS = ["Fixed", "Auto"] as const;

export type TextFit = (typeof TEXT_FITS)[number];

export const DEFAULT_TEXT_FIT: TextFit = "Fixed";

export const MAX_HREF_BYTES = 2048;

// ASCII only, so the length cap counts bytes; crates/server/src/object.rs checks the same shape.
export const HREF_PATTERN =
  "^[Hh][Tt][Tt][Pp][Ss]?://([A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.?|\\[[0-9A-Fa-f:.]+\\])(:[0-9]{1,5})?([/?#][!-~]*)?$";

const HREF = new RegExp(HREF_PATTERN);

export const isHref = (value: string): boolean =>
  value.length <= MAX_HREF_BYTES && HREF.test(value);

export const parseHref = (input: string): string | undefined => {
  const trimmed = input.trim();
  if (trimmed === "") return undefined;
  const withScheme = /^[a-z][a-z0-9+.-]*:/i.test(trimmed) ? trimmed : `https://${trimmed}`;
  if (!URL.canParse(withScheme)) return undefined;
  const url = new URL(withScheme);
  if (url.protocol !== "http:" && url.protocol !== "https:") return undefined;
  if (!url.hostname.includes(".") && !url.hostname.startsWith("[") && url.hostname !== "localhost")
    return undefined;
  return isHref(url.href) ? url.href : undefined;
};

export type TextStyle = {
  font: TextFont;
  bold: boolean;
  italic: boolean;
  fit: TextFit;
};

export type Styleable = {
  font?: TextFont | undefined;
  bold?: boolean | undefined;
  italic?: boolean | undefined;
  fit?: TextFit | undefined;
};

export const textStyleOf = (object: Styleable): TextStyle => ({
  font: object.font ?? DEFAULT_TEXT_FONT,
  bold: object.bold ?? false,
  italic: object.italic ?? false,
  fit: object.fit ?? DEFAULT_TEXT_FIT,
});

export const withTextStyle = <T extends Styleable>(object: T): T & TextStyle => ({
  ...object,
  ...textStyleOf(object),
});
import { Encoder } from "cbor-x";
import { validate } from "../generated/validate.js";
import { withRgb } from "./colour";
import type { StallionObject } from "./model";
import { withStyle } from "./style";
import { withTextStyle } from "./text-style";
import { withWidth } from "./width";

export type DecodeResult = { ok: true; value: StallionObject } | { ok: false; error: string };

const cbor = new Encoder({ useRecords: false, mapsAsObjects: true, variableMapSize: true });

const normalise = (object: StallionObject): StallionObject => {
  if (object.type === "Sticky" || object.type === "Text") return withTextStyle(object);
  return withStyle(withWidth(withRgb(object)));
};

const describeErrors = (): string =>
  (validate.errors ?? []).map((e) => `${e.instancePath || "/"} ${e.message ?? ""}`).join("; ");

export const encode = (object: StallionObject): Uint8Array => {
  if (!validate(object)) {
    throw new TypeError(`Cannot encode an invalid object: ${describeErrors()}`);
  }
  return cbor.encode(normalise(object));
};

export const decode = (bytes: Uint8Array): DecodeResult => {
  const value: unknown = cbor.decode(bytes);
  if (!validate(value)) {
    return { ok: false, error: describeErrors() };
  }
  return { ok: true, value: normalise(value) };
};
export { type DecodeResult, decode, encode } from "./codec";
export * from "./colour";
export * from "./frame";
export * from "./ink";
export * from "./model";
export * from "./shape";
export * from "./sticky";
export * from "./style";
export * from "./text-style";
export * from "./width";
export const STROKE_STYLES = ["Pen", "Highlighter", "Dashed", "Uniform"] as const;

export type StrokeStyle = (typeof STROKE_STYLES)[number];

export const DEFAULT_STROKE_STYLE: StrokeStyle = "Pen";

export type Styled = { style?: StrokeStyle | undefined };

export const styleOf = ({ style }: Styled): StrokeStyle => style ?? DEFAULT_STROKE_STYLE;

export const withStyle = <T extends Styled>(object: T): T & { style: StrokeStyle } => ({
  ...object,
  style: styleOf(object),
});
