    ) -> StallionObject {
        StallionObject::Stroke(Stroke {
            object_id: "stroke-0001".into(),
            native_zoom: -3,
            bbox: Bbox {
                min_x: 10.0,
                min_y: 12.5,
                max_x: 42.0,
                max_y: 30.25,
            },
            colour,
            rgb,
            size: PencilSize::Medium,
