  }, []);
  const [target, setTarget] = useState<TextTarget | undefined>(undefined);
  const targetRef = useRef<TextTarget | undefined>(undefined);
  const onTarget = useCallback((next: TextTarget | undefined) => {
    targetRef.current = next;
    setTarget(next);
  }, []);
