import { writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { accessHeaders, routeAccessHeaders } from "../npm-scripts/env.mjs";

const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const OUT = join(homedir(), "development", ".tmp", "stallion-shapetools");
const DEPLOYED_AT = Date.parse(process.argv[2]);
const problems = [];

const randomBoardId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let value = 0n;
  for (const byte of bytes) value = (value << 8n) | BigInt(byte);
  return value.toString(36).padStart(25, "0");
};

const watch = (page, label) => {
  page.on("console", (m) => {
    if (m.type() === "error") problems.push(`${label}: console ${m.text()}`);
  });
  page.on("pageerror", (e) => problems.push(`${label}: pageerror ${e.message}`));
};

const tapper = (page, touch) => async (points) => {
  if (!touch) {
    const [first, ...rest] = points;
    await page.mouse.move(first.x, first.y);
    await page.mouse.down();
    for (const p of rest) await page.mouse.move(p.x, p.y);
    await page.mouse.up();
    return;
  }
  const cdp = await page.context().newCDPSession(page);
  const send = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
    });
  const [first, ...rest] = points;
  await send("touchStart", first);
  for (const p of rest) await send("touchMove", p);
  await send("touchEnd");
  await cdp.detach();
};

const line = (a, b) =>
  Array.from({ length: 24 }, (_, i) => ({
    x: a.x + ((b.x - a.x) * i) / 23,
    y: a.y + ((b.y - a.y) * i) / 23,
  }));

const openBoard = async (browser, device, url, label) => {
  const context = await browser.newContext({ ...device, colorScheme: "light" });
  await routeAccessHeaders(context, ORIGIN);
  const page = await context.newPage();
  watch(page, label);
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(1500);
  return { context, page };
};

const button = (page, name) => page.getByRole("button", { name, exact: true }).first();

const reveal = async (page, name) => {
  if (await button(page, name).isVisible()) return;
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  if (await button(page, name).isVisible()) return;
  await page.locator("[data-toolbar-flip]").click();
  await page.waitForTimeout(500);
};

const pick = async (page, name) => {
  await reveal(page, name);
  await button(page, name).click();
};

const drawRectangle = async (page, draw, from, to) => {
  await pick(page, "Rectangle");
  await draw(line(from, to));
  await page.waitForTimeout(400);
};

const toolbarShot = async (browser, name, device, touch) => {
  const { context, page } = await openBoard(browser, device, `${ORIGIN}/b/${randomBoardId()}`, name);
  const draw = tapper(page, touch);
  const { width, height } = page.viewportSize();
  const from = { x: Math.round(width * 0.45), y: Math.round(height * 0.5) };
  const to = { x: Math.round(width * 0.85), y: Math.round(height * 0.75) };
  await drawRectangle(page, draw, from, to);
  await pick(page, "Select tool");
  await draw([{ x: from.x, y: Math.round((from.y + to.y) / 2) }]);
  const toolbar = page.getByRole("toolbar", { name: "Shape", exact: true });
  await toolbar.waitFor({ state: "visible", timeout: 5000 });
  await toolbar.getByLabel("Fill colour").fill("#f76b15");
  await page.waitForTimeout(500);
  const path = join(OUT, `toolbar-${name}.png`);
  writeFileSync(path, await page.screenshot());
  await context.close();
  return path;
};

const compositeShot = async (browser) => {
  const device = devices["Galaxy Tab S9"];
  const { context, page } = await openBoard(browser, device, `${ORIGIN}/b/${randomBoardId()}`, "composite");
  const draw = tapper(page, true);
  const { width, height } = page.viewportSize();
  await pick(page, "40 px pencil");
  await pick(page, "Pencil");
  await draw(line({ x: width * 0.35, y: height * 0.55 }, { x: width * 0.9, y: height * 0.6 }));
  await page.waitForTimeout(400);
  const from = { x: Math.round(width * 0.45), y: Math.round(height * 0.45) };
  const to = { x: Math.round(width * 0.8), y: Math.round(height * 0.72) };
  await drawRectangle(page, draw, from, to);
  await pick(page, "Select tool");
  await draw([{ x: from.x, y: Math.round(from.y + 30) }]);
  const toolbar = page.getByRole("toolbar", { name: "Shape", exact: true });
  await toolbar.waitFor({ state: "visible", timeout: 5000 });
  await toolbar.getByLabel("Fill colour").fill("#0090ff");
  await page.waitForTimeout(300);
  await toolbar.getByRole("button", { name: "Outline" }).click();
  await page.waitForTimeout(300);
  await toolbar.getByLabel("Opacity").fill("50");
  await page.waitForTimeout(500);
  const selectedPath = join(OUT, "composite-selected.png");
  writeFileSync(selectedPath, await page.screenshot());
  await page.reload({ waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(2000);
  const path = join(OUT, "composite-fill-no-outline-50.png");
  writeFileSync(path, await page.screenshot());
  await context.close();
  return [selectedPath, path];
};

const oldBoards = async (browser) => {
  const response = await fetch(`${ORIGIN}/api/me/boards`, { headers: accessHeaders() });
  if (!response.ok) throw new Error(`boards list answered ${response.status}`);
  const rows = (await response.json()).filter(
    (row) => row.removedAt === 0 && row.lastOpened < DEPLOYED_AT && row.thumbnail,
  );
  const shots = [];
  for (const row of rows.slice(0, 6)) {
    const { context, page } = await openBoard(
      browser,
      devices["Galaxy Tab S9"],
      `${ORIGIN}/b/${row.boardId}`,
      `old ${row.boardId}`,
    );
    const path = join(OUT, `old-${row.boardId}.png`);
    writeFileSync(path, await page.screenshot());
    const thumb = join(OUT, `old-${row.boardId}-thumbnail-before.png`);
    writeFileSync(thumb, Buffer.from(row.thumbnail.split(",")[1], "base64"));
    shots.push(`${path} (opened ${new Date(row.lastOpened).toISOString()})`);
    await context.close();
  }
  return shots;
};

const browser = await chromium.launch({ headless: true });
